Use symmetry to evaluate $\int_{-2}^{2}\left(x^{3}+5x\right)dx$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}, x=1.05cm, y=0.15cm]
\fill[gray!35, domain=-2:0, variable=\x] (-2,0) -- plot ({\x},{\x*\x*\x+5*\x}) -- (0,0) -- cycle;
\fill[gray!35, domain=0:2, variable=\x] (0,0) -- plot ({\x},{\x*\x*\x+5*\x}) -- (2,0) -- cycle;
\draw[->] (-3.1,0) -- (3.1,0) node[right] {$x$};
\draw[->] (0,-24) -- (0,24) node[above] {$y$};
\draw[thick, <->, domain=-2.2:2.2, smooth, samples=120, variable=\x] plot ({\x},{\x*\x*\x+5*\x});
\node[above left] at (-2,0) {$-2$};
\node[below right] at (2,0) {$2$};
\node[left] at (0,10) {$10$};
\node[left] at (0,-10) {$-10$};
\end{tikzpicture}
[/tikz]

Use symmetry to evaluate $\int_{-4}^{4} x^{2}\,dx$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}, x=0.58cm, y=0.24cm]
\fill[gray!35, domain=-4:4, variable=\x] (-4,0) -- plot ({\x},{\x*\x}) -- (4,0) -- cycle;
\draw[->] (-5.8,0) -- (5.8,0) node[right] {$x$};
\draw[->] (0,-4.4) -- (0,24) node[above] {$y$};
\draw[thick, <->, domain=-4.6:4.6, smooth, samples=100, variable=\x] plot ({\x},{\x*\x});
\node[below left] at (-4,0) {$-4$};
\node[below right] at (4,0) {$4$};
\node[left] at (0,10) {$10$};
\node[left] at (0,20) {$20$};
\end{tikzpicture}
[/tikz]

