\begin{tikzpicture}[every node/.style={font=\large}, x=0.62cm, y=0.011cm]
\fill[gray!35, domain=-3:0, variable=\x] (-3,0) -- plot ({\x},{\x*\x*\x*\x*\x+\x*\x}) -- (0,0) -- cycle;
