\fill[gray!35, domain=1.0665:2, variable=\x] (1.0665,0) -- plot ({\x},{3*\x*\x*\x*\x-\x*\x*\x+5*\x-8}) -- (2,0) -- cycle;
\draw[->] (-2.9,0) -- (2.9,0) node[right] {$x$};
\draw[->] (0,-24) -- (0,58) node[above] {$y$};
\draw[thick, <->, domain=-2.15:2.1, smooth, samples=160, variable=\x] plot ({\x},{3*\x*\x*\x*\x-\x*\x*\x+5*\x-8});
\node[above left] at (-2,0) {$-2$};
\node[below right] at (2,0) {$2$};
\node[left] at (0,20) {$20$};
\node[left] at (0,-20) {$-20$};
\end{tikzpicture}
[/tikz]

